// pathHasSegment reports whether segment appears as a complete path segment
// in p, using either Unix or Windows separators.
func pathHasSegment(p, segment string) bool {
	for _, s := range strings.FieldsFunc(p, func(r rune) bool { return r == '/' || r == '\\' }) {
		if s == segment {
			return true
		}
	}
	return false
}
